  ctx.beginPath(); ctx.ellipse(8.2, -33 + bob, 4.3, 3.5, 0.2, 0, TAU); ctx.fill();
  ctx.strokeStyle = rgba(accent, 0.7); ctx.lineWidth = 0.8; ctx.stroke();
