  inBounds(x, y) { return x >= 1 && y >= 1 && x < SIZE - 1 && y < SIZE - 1; }
  heightAt(x, y) {
    if (!this.inBounds(x, y)) return 0;
    return this.height[this.idx(Math.floor(x), Math.floor(y))] || 0;
  }
  tileAt(x, y) {
