/* AETHERIA — 2.5D isometric fantasy UI */
:root {
  --ink-0: #050a10;
  --ink-1: #08121b;
  --ink-2: #0d1a24;
  --ink-3: #14242f;
  --ink-4: #1b303d;
  --line: rgba(205, 177, 112, 0.22);
  --line-soft: rgba(205, 177, 112, 0.11);
  --gold: #d5b572;
  --gold-bright: #f4dda1;
  --gold-deep: #8c6f3e;
  --parchment: #ece3ce;
  --text: #e5e3d8;
  --muted: #8d9ba4;
  --muted-2: #62737f;
  --angel: #a8d8ff;
  --demon: #ff9a72;
  --hp: #ba3f47;
  --hp-2: #e06b63;
  --mana: #3c7cc0;
  --mana-2: #73b7ed;
  --green: #6fce89;
  --panel: rgba(8, 18, 27, 0.94);
  --panel-2: rgba(13, 27, 39, 0.88);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, "Iowan Old Style", Georgia, serif;
  --sans: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #050a10; color: var(--text); font-family: var(--sans); }
body { -webkit-tap-highlight-color: transparent; }
button, input, select { font: inherit; }
button { color: inherit; border: 0; cursor: pointer; background: none; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 1px solid var(--gold); outline-offset: 2px; }
svg { width: 20px; height: 20px; fill: currentColor; }
.hidden { display: none !important; }
.svg-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
#app { position: fixed; inset: 0; background: #050a10; }
#gameCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: crosshair; }

/* ---------- shared controls ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 38px; padding: 9px 18px; border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(35, 53, 63, .82), rgba(11, 23, 32, .9));
  color: var(--parchment); letter-spacing: .04em; text-transform: uppercase;
  font-size: 11px; font-weight: 700; position: relative; transition: .18s ease;
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
}
.btn:hover { border-color: rgba(236, 207, 143, .55); background: linear-gradient(180deg, rgba(48, 70, 82, .92), rgba(16, 31, 41, .95)); transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn svg { width: 15px; height: 15px; }
.btn.small { min-height: 30px; padding: 6px 11px; font-size: 9px; }
.btn-primary {
  background: linear-gradient(180deg, #b48f4d, #6f552d 70%, #4d391d);
  border-color: rgba(255, 230, 166, .7); color: #fff4d6;
  box-shadow: 0 0 0 1px rgba(20, 15, 8, .6) inset, 0 8px 24px rgba(202, 155, 75, .18);
  text-shadow: 0 1px 1px rgba(0,0,0,.5);
}
.btn-primary:hover { background: linear-gradient(180deg, #cba75e, #886b38 70%, #5d4926); border-color: #ffe7a6; }
.btn-ghost { background: rgba(9, 20, 29, .55); }
.btn-danger { border-color: rgba(209, 93, 85, .45); color: #ffb2a8; }
.btn-large { min-height: 54px; padding: 13px 35px; font-size: 13px; letter-spacing: .14em; }
.btn[disabled], .btn.disabled { opacity: .38; cursor: not-allowed; transform: none !important; }
.text-input {
  width: 100%; height: 38px; padding: 7px 11px; color: var(--parchment);
  background: rgba(5, 12, 19, .7); border: 1px solid var(--line); border-radius: 2px;
  letter-spacing: .03em; font-size: 13px;
}
