.toast.fade { animation: toastOut .35s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(10px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-7px); } }
.region-banner { position: absolute; top: 27%; left: 50%; transform: translateX(-50%); text-align: center; padding: 18px 70px; background: linear-gradient(90deg, transparent, rgba(5, 14, 20, .84) 22%, rgba(5, 14, 20, .84) 78%, transparent); border-top: 1px solid rgba(220, 185, 111, .22); border-bottom: 1px solid rgba(220, 185, 111, .22); pointer-events: none; animation: regionIn .8s ease both; }
