.region-banner > span:last-child { font-size: 9px; letter-spacing: .12em; color: #9ca8a2; }
@keyframes regionIn { from { opacity: 0; transform: translate(-50%, -8px); } to { opacity: 1; transform: translate(-50%, 0); } }
.save-flash { position: absolute; right: 24px; bottom: 20px; padding: 5px 9px; background: rgba(5, 13, 19, .8); border: 1px solid rgba(104, 171, 134, .22); color: #86b89b; font-size: 7px; letter-spacing: .08em; opacity: 0; transition: opacity .3s; }
.save-flash.show { opacity: 1; }
.damage-flash { position: absolute; inset: 0; background: radial-gradient(circle, transparent 45%, rgba(132, 20, 23, .5)); opacity: 0; pointer-events: none; transition: opacity .16s; }
