70:   _bindEvents() {
71:     this._onResize = () => this.resize();
72:     window.addEventListener('resize', this._onResize);
73:     const blocked = (target) => target && (target.closest('input, textarea, select, [contenteditable]') || this.modalOpen);
74:     this._onKeyDown = (e) => {
75:       if (blocked(e.target)) return;
76:       const key = e.key.toLowerCase();
77:       if (['w', 'arrowup'].includes(key)) { this.input.up = true; e.preventDefault(); }
78:       if (['s', 'arrowdown'].includes(key)) { this.input.down = true; e.preventDefault(); }
79:       if (['a', 'arrowleft'].includes(key)) { this.input.left = true; e.preventDefault(); }
80:       if (['d', 'arrowright'].includes(key)) { this.input.right = true; e.preventDefault(); }
81:       if (key === ' ' || key === 'spacebar') { this.tryAttack(); e.preventDefault(); }
82:       if (key === 'q') { this.trySkill(); e.preventDefault(); }
83:       if (key === 'e' || key === 'f') { this.interact(); e.preventDefault(); }
84:       if (key === 'r') { this.usePotion('health'); }
85:       if (key === 'm') this.ui?.openPanel('map');
86:       if (key === 'i' || key === 'b') this.ui?.openPanel('inventory');
87:     };
88:     this._onKeyUp = (e) => {
89:       const key = e.key.toLowerCase();
90:       if (['w', 'arrowup'].includes(key)) this.input.up = false;
91:       if (['s', 'arrowdown'].includes(key)) this.input.down = false;
92:       if (['a', 'arrowleft'].includes(key)) this.input.left = false;
93:       if (['d', 'arrowright'].includes(key)) this.input.right = false;
94:     };
95:     window.addEventListener('keydown', this._onKeyDown);
96:     window.addEventListener('keyup', this._onKeyUp);
97:     this._onCanvasClick = (e) => {
98:       if (this.modalOpen || !this.player) return;
99:       const r = this.canvas.getBoundingClientRect();
100:       const sx = e.clientX - r.left, sy = e.clientY - r.top;
101:       // Ignore controls (they're DOM, but be defensive on mobile).
102:       if (e.target !== this.canvas) return;
103:       this.setMoveTargetFromScreen(sx, sy);
104:     };
105:     this.canvas.addEventListener('pointerdown', this._onCanvasClick);
106:   }
