163:         this.player.x = this.state.location.x; this.player.y = this.state.location.y;
164:       } else {
165:         this.player.x = region.village.x; this.player.y = region.village.y + 2.3;
166:       }
167:     } else if (opts.spawn === 'village') {
168:       this.player.x = region.village.x; this.player.y = region.village.y + 2.5;
169:     } else if (opts.spawn === 'dungeon') {
