171:     } else if (typeof opts.spawn === 'object') {
172:       this.player.x = opts.spawn.x; this.player.y = opts.spawn.y;
173:     }
174:     this.player.regionId = regionId;
175:     this.player.dead = false;
176:     this.player.invuln = 1.2;
177:     this.enemies = this.world.spawns.map((s, index) => this.makeEnemy(s, index));
178:     this.projectiles = [];
179:     this.effects = [];
180:     this.zones = [];
181:     this.pickups = [];
182:     this.texts = [];
183:     this.bossVisible = null;
184:     const p = this.world.iso(this.player.x, this.player.y);
185:     this.camera.x = p.x; this.camera.y = p.y;
186:     this.initWeather();
