203:       hp: def.hp, maxHp: def.hp, alive: true, isBoss: !!spawn.boss || !!def.boss, elite: !!spawn.elite || !!def.elite,
204:       facing: 1, state: 'idle', aggro: false, attackTimer: 0.8 + Math.random(), attackAnim: 0,
205:       hitFlash: 0, respawnTimer: 0, walkPhase: Math.random() * TAU, moving: false, telegraph: 0,
206:       seed: index * 2.3, spawn, p,
