210:   initWeather() {
211:     const cfg = WEATHER[this.region.weather] || WEATHER.petals;
212:     this.weather = [];
213:     for (let i = 0; i < cfg.count; i++) {
214:       this.weather.push({
215:         x: Math.random() * this.width, y: Math.random() * this.height,
216:         vx: (Math.random() - 0.5) * cfg.sway, vy: cfg.speed * (0.5 + Math.random()),
217:         size: cfg.size[0] + Math.random() * (cfg.size[1] - cfg.size[0]),
218:         phase: Math.random() * TAU, color: cfg.color[Math.floor(Math.random() * cfg.color.length)],
219:         alpha: 0.25 + Math.random() * 0.55,
220:       });
221:     }
222:   }
