224:   loop(now) {
225:     if (!this.running) return;
226:     const dtRaw = Math.min((now - this.lastTime) / 1000, 0.05);
227:     this.lastTime = now;
228:     if (!this.paused) {
229:       if (this.hitStop > 0) { this.hitStop -= dtRaw; }
230:       else this.update(dtRaw);
231:     }
232:     this.render();
233:     requestAnimationFrame((t) => this.loop(t));
234:   }
