236:   update(dt) {
237:     this.time += dt;
238:     if (!this.player || !this.world) return;
239:     this.accumSave += dt;
240:     this.state.stats.playSeconds = (this.state.stats.playSeconds || 0) + dt;
241:     if (this.accumSave > 12) { this.saveSoon(); this.accumSave = 0; }
242:     this.updatePlayer(dt);
243:     this.updateEnemies(dt);
244:     this.updateProjectiles(dt);
245:     this.updateZones(dt);
246:     this.updateEffects(dt);
247:     this.updatePickups(dt);
248:     this.updateCamera(dt);
249:     this.updateWeather(dt);
250:     this.interactable = this.world.nearInteractable(this.player.x, this.player.y, 1.55);
251:     if (this.playerAttackCooldown > 0) this.playerAttackCooldown -= dt;
252:     if (this.skillCooldown > 0) this.skillCooldown -= dt;
253:     if (this.potionCooldown > 0) this.potionCooldown -= dt;
254:     if (this.player.attackTimer > 0) this.player.attackTimer = Math.max(0, this.player.attackTimer - dt);
255:     if (this.player.invuln > 0) this.player.invuln -= dt;
256:     if (this.player.hitFlash > 0) this.player.hitFlash -= dt;
257:     // out-of-combat regen
258:     const inCombat = this.enemies.some((e) => e.alive && e.aggro && Math.hypot(e.x - this.player.x, e.y - this.player.y) < 7);
259:     if (inCombat) this.combatTimer = 4; else if (this.combatTimer > 0) this.combatTimer -= dt;
260:     if (!this.combatTimer || this.combatTimer <= 0) {
261:       const stats = computeStats(this.state);
262:       const angel = this.state.profile.faction === 'angel';
263:       this.state.hp = Math.min(stats.maxHp, this.state.hp + dt * (1.3 + stats.maxHp * 0.006) * (angel ? 1.12 : 1));
264:       this.state.mana = Math.min(stats.maxMana, this.state.mana + dt * (1.9 + stats.maxMana * 0.007) * (angel ? 1.12 : 1));
265:     }
266:     this.state.hp = clamp(this.state.hp, 0, computeStats(this.state).maxHp);
267:     this.state.mana = clamp(this.state.mana, 0, computeStats(this.state).maxMana);
268:     if (this.state.hp <= 0 && !this.player.dead) this.die();
269:     // boss bar / UI
270:     const boss = this.enemies.find((e) => e.isBoss && e.alive && Math.hypot(e.x - this.player.x, e.y - this.player.y) < 15);
271:     if ((boss?.id || null) !== (this.bossVisible?.id || null)) {
272:       this.bossVisible = boss || null;
273:       this.ui?.setBoss(boss);
274:     } else if (boss && this.bossVisible) this.bossVisible = boss;
275:     this.ui?.tick(dt);
276:   }
