278:   updatePlayer(dt) {
279:     const p = this.player;
280:     if (p.dead) return;
281:     let mx = (this.input.right ? 1 : 0) - (this.input.left ? 1 : 0);
282:     let my = (this.input.down ? 1 : 0) - (this.input.up ? 1 : 0);
283:     if (this.input.vector && Math.hypot(this.input.vector.x, this.input.vector.y) > 0.05) {
284:       mx = this.input.vector.x; my = this.input.vector.y;
285:     }
286:     // click/tap-to-move fallback
287:     if (Math.hypot(mx, my) < 0.08 && this.input.target && !this.modalOpen) {
288:       const dx = this.input.target.x - p.x, dy = this.input.target.y - p.y;
289:       const d = Math.hypot(dx, dy);
290:       if (d > 0.16) { mx = dx / d; my = dy / d; } else this.input.target = null;
291:     }
292:     const mag = Math.hypot(mx, my);
293:     if (mag > 1) { mx /= mag; my /= mag; }
294:     const stats = computeStats(this.state);
295:     let speed = stats.speed;
296:     if (this.state.mounted && this.state.equipped.mount && MOUNTS[this.state.equipped.mount]) speed *= 1 + MOUNTS[this.state.equipped.mount].speed;
297:     const moving = mag > 0.08;
298:     p.moving = moving;
299:     if (moving) {
300:       this.input.target = null;
301:       const nx = p.x + mx * speed * dt;
302:       const ny = p.y + my * speed * dt;
303:       const resolved = this.world.resolveMove(p.x, p.y, nx, ny, 0.27);
304:       p.x = resolved.x; p.y = resolved.y;
305:       p.walkPhase += dt * (7.5 + speed);
306:       p.facing = mx >= 0 ? 1 : -1;
307:       p.direction = Math.abs(my) > Math.abs(mx) ? (my < 0 ? 'up' : 'down') : 'side';
308:       if (Math.random() < dt * 8) {
309:         const iso = this.world.iso(p.x, p.y);
310:         this.effects.push({ type: 'step', x: iso.x, y: iso.y, time: 0, dur: 1.0, color: this.region.palette.path[0] });
311:       }
312:     } else {
313:       p.walkPhase += dt * 1.5;
314:       if (p.direction === 'side') p.direction = 'down';
315:     }
316:     if (this.state.mounted && this.state.equipped.mount) {
317:       // pet and mount stay visual only; no extra simulation burden
318:     }
319:     // nearby loot pickup (magnet-like)
320:     for (const pickup of this.pickups) {
321:       if (pickup.collected) continue;
322:       const d = Math.hypot(pickup.x - p.x, pickup.y - p.y);
323:       if (d < 1.5) pickup.magnet = true;
324:       if (pickup.magnet) {
325:         const sp = 3.5 + (1 - d / 2) * 4;
326:         const dx = p.x - pickup.x, dy = p.y - pickup.y;
327:         const dd = Math.hypot(dx, dy) || 1;
328:         pickup.x += dx / dd * sp * dt; pickup.y += dy / dd * sp * dt;
329:         if (dd < 0.38) this.collectPickup(pickup);
330:       }
331:     }
332:     // pet follow
333:     if (this.state.equipped.pet) {
334:       if (!this.petPos) this.petPos = { x: p.x - 1, y: p.y + 0.8 };
335:       const tx = p.x - 0.85 * p.facing, ty = p.y + 0.95;
336:       this.petPos.x = lerp(this.petPos.x, tx, dt * 3);
337:       this.petPos.y = lerp(this.petPos.y, ty, dt * 3);
338:     }
339:     // save position roughly
340:     if (Math.floor(this.time * 2) !== this._lastSaveStep) {
341:       this._lastSaveStep = Math.floor(this.time * 2);
342:       this.state.location = { regionId: this.regionId, x: p.x, y: p.y };
343:     }
344:   }
345: 
346:   updateEnemies(dt) {
347:     const p = this.player;
348:     const stats = computeStats(this.state);
349:     for (const e of this.enemies) {
350:       if (!e.alive) {
351:         if (e.respawnTimer > 0) e.respawnTimer -= dt;
352:         if (e.respawnTimer <= 0 && !e.isBoss && !e.def.boss) {
353:           e.alive = true; e.hp = e.maxHp; e.x = e.homeX; e.y = e.homeY; e.aggro = false; e.state = 'idle';
354:         }
355:         continue;
356:       }
357:       e.hitFlash = Math.max(0, e.hitFlash - dt);
358:       e.attackAnim = Math.max(0, e.attackAnim - dt);
359:       if (e.telegraph > 0) e.telegraph -= dt;
360:       if (p.dead) { e.aggro = false; e.moving = false; continue; }
361:       const dx = p.x - e.x, dy = p.y - e.y;
362:       const dist = Math.hypot(dx, dy);
363:       const aggroRange = e.isBoss ? 15 : (e.def.aggro || 5.5);
364:       if (!e.aggro && dist < aggroRange) e.aggro = true;
365:       const leash = e.isBoss ? 18 : 12;
366:       if (e.aggro && Math.hypot(e.homeX - e.x, e.homeY - e.y) > leash) {
367:         e.aggro = false;
368:         e.returning = true;
369:       }
370:       if (e.returning) {
371:         const hx = e.homeX - e.x, hy = e.homeY - e.y, hd = Math.hypot(hx, hy);
372:         if (hd < 0.4) { e.returning = false; e.hp = Math.min(e.maxHp, e.hp + 25); }
373:         else { e.x += hx / hd * e.def.speed * dt * 0.8; e.y += hy / hd * e.def.speed * dt * 0.8; e.moving = true; }
374:         continue;
375:       }
376:       if (e.aggro && dist > 0.9) {
377:         const ranged = e.def.ranged;
378:         const range = ranged ? 3.9 : (e.isBoss ? 1.55 : 1.15);
379:         if (dist > range) {
380:           const nx = e.x + dx / (dist || 1) * e.def.speed * dt;
381:           const ny = e.y + dy / (dist || 1) * e.def.speed * dt;
382:           const resolved = this.world.resolveMove(e.x, e.y, nx, ny, e.def.radius || 0.3);
383:           e.x = resolved.x; e.y = resolved.y;
384:           e.moving = true; e.walkPhase += dt * (4 + e.def.speed);
385:           e.facing = dx >= 0 ? 1 : -1;
386:         } else {
387:           e.moving = false;
388:           if (!ranged && e.attackTimer <= 0) {
389:             e.attackTimer = e.isBoss ? 1.1 : 1.55;
390:             e.attackAnim = 0.36;
391:             this.damagePlayer(e.def.damage, e);
392:           }
393:           if (ranged && e.attackTimer <= 0) {
394:             e.attackTimer = 1.8;
395:             e.attackAnim = 0.4;
396:             const ang = Math.atan2(dy, dx);
397:             this.projectiles.push({ owner: 'enemy', x: e.x, y: e.y, tx: p.x, ty: p.y, vx: Math.cos(ang) * 5, vy: Math.sin(ang) * 5, life: 3, damage: e.def.damage * 0.8, color: e.def.colors[2], radius: 0.15 });
398:           }
399:         }
400:         if (e.isBoss && e.attackTimer <= 0 && dist < 7) {
401:           e.attackTimer = 5.8;
402:           e.telegraph = 1.35;
403:           const tx = p.x, ty = p.y;
404:           this.zones.push({
405:             owner: 'enemy', type: 'telegraph', x: tx, y: ty, radius: 2.5, delay: 1.35, time: 0,
406:             color: e.def.colors[2], damage: e.def.damage * 1.7, done: false,
407:           });
408:           this.ui?.toast('danger', `${e.def.name} is gathering a devastating strike!`);
409:         }
410:       } else if (!e.aggro) {
411:         e.moving = Math.random() < dt * 0.4;
412:         e.walkPhase += dt * (e.moving ? 3 : 1);
413:       }
414:       if (e.attackTimer > 0) e.attackTimer -= dt;
415:       // soft separation so packs don't perfectly stack
416:       for (const other of this.enemies) {
417:         if (other === e || !other.alive) continue;
418:         const sx = e.x - other.x, sy = e.y - other.y;
419:         const sd = Math.hypot(sx, sy);
420:         const min = (e.def.radius || .3) + (other.def.radius || .3);
421:         if (sd > 0.001 && sd < min) {
422:           e.x += sx / sd * 0.3 * dt; e.y += sy / sd * 0.3 * dt;
423:         }
424:       }
425:       e.x = clamp(e.x, 1, this.world.size - 1); e.y = clamp(e.y, 1, this.world.size - 1);
426:     }
427:     // update boss bar text
428:     if (this.bossVisible && this.ui) this.ui.updateBossHp(this.bossVisible);
429:   }
430: 
431:   updateProjectiles(dt) {
432:     for (const pr of this.projectiles) {
433:       pr.life -= dt;
434:       if (pr.owner === 'player' && pr.target && pr.target.alive) {
435:         const ang = Math.atan2(pr.target.y - pr.y, pr.target.x - pr.x);
436:         const speed = Math.hypot(pr.vx, pr.vy);
437:         pr.vx = lerp(pr.vx, Math.cos(ang) * speed, dt * 3.5);
438:         pr.vy = lerp(pr.vy, Math.sin(ang) * speed, dt * 3.5);
439:       }
440:       pr.x += pr.vx * dt; pr.y += pr.vy * dt;
441:       if (pr.owner === 'player') {
442:         for (const e of this.enemies) {
443:           if (!e.alive) continue;
444:           if (Math.hypot(e.x - pr.x, e.y - pr.y) < (e.def.radius || .35) + (pr.radius || .2)) {
445:             this.damageEnemy(e, pr.damage, pr.crit, pr.color);
446:             this.spawnImpact(pr.x, pr.y, pr.color, 6);
447:             pr.life = 0; break;
448:           }
449:         }
450:       } else {
451:         if (Math.hypot(this.player.x - pr.x, this.player.y - pr.y) < 0.38 && !this.player.dead) {
452:           this.damagePlayer(pr.damage, null);
453:           this.spawnImpact(pr.x, pr.y, pr.color, 5);
454:           pr.life = 0;
455:         }
456:       }
457:       if (pr.life <= 0) pr.dead = true;
458:     }
459:     this.projectiles = this.projectiles.filter((p) => p.life > 0);
460:   }
461: 
462:   updateZones(dt) {
463:     for (const z of this.zones) {
464:       z.time += dt;
465:       if (z.type === 'telegraph') {
466:         if (!z.done && z.time >= z.delay) {
467:           z.done = true;
468:           const iso = this.world.iso(z.x, z.y);
469:           this.spawnImpact(z.x, z.y, z.color, 22);
470:           this.camera.shake = 10;
471:           if (Math.hypot(this.player.x - z.x, this.player.y - z.y) < z.radius && !this.player.dead) this.damagePlayer(z.damage, null);
472:           this.effects.push({ type: 'shock', x: iso.x, y: iso.y, color: z.color, time: 0, dur: 0.5, radius: z.radius * TILE });
473:         }
474:         continue;
475:       }
476:       z.tickTimer -= dt;
477:       if (z.tickIndex < z.ticks && z.tickTimer <= 0) {
478:         z.tickTimer = z.interval;
479:         z.tickIndex++;
480:         if (z.owner === 'player') {
481:           for (const e of this.enemies) {
482:             if (!e.alive) continue;
483:             if (Math.hypot(e.x - z.x, e.y - z.y) < z.radius) this.damageEnemy(e, z.damage, Math.random() < computeStats(this.state).crit, z.color);
484:           }
485:         }
486:         const iso = this.world.iso(z.x, z.y);
487:         this.effects.push({ type: 'zonePulse', x: iso.x, y: iso.y, color: z.color, time: 0, dur: 0.38, radius: z.radius * TILE, delay: z.tickIndex === z.ticks });
488:       }
489:       if (z.tickIndex >= z.ticks) z.done = true;
490:     }
491:     this.zones = this.zones.filter((z) => !z.done && z.time < 12);
492:   }
493: 
494:   updateEffects(dt) {
495:     for (const fx of this.effects) { fx.time += dt; if (fx.vy) fx.y += fx.vy * dt; }
496:     this.effects = this.effects.filter((fx) => fx.time < fx.dur);
497:     for (const tx of this.texts) { tx.time += dt; tx.y += tx.vy * dt; tx.vy += 18 * dt; }
498:     this.texts = this.texts.filter((tx) => tx.time < tx.dur);
499:     this.camera.shake = Math.max(0, this.camera.shake - dt * 18);
500:     if (this.camera.shake > 0) {
501:       this.camera.shakeX = (Math.random() - .5) * this.camera.shake;
502:       this.camera.shakeY = (Math.random() - .5) * this.camera.shake;
503:     } else { this.camera.shakeX = 0; this.camera.shakeY = 0; }
504:   }
505: 
506:   updatePickups(dt) {
507:     for (const p of this.pickups) p.time += dt;
508:   }
509: 
510:   updateCamera(dt) {
511:     const p = this.world.iso(this.player.x, this.player.y);
512:     // lead camera slightly in the direction of movement; keeps zoomed-out scenes readable.
513:     const lead = this.player.moving ? 20 * this.player.facing : 0;
514:     this.camera.x = lerp(this.camera.x, p.x + lead, 1 - Math.exp(-dt * WORLD.cameraEase));
515:     this.camera.y = lerp(this.camera.y, p.y, 1 - Math.exp(-dt * WORLD.cameraEase));
516:     this.camera.zoom = lerp(this.camera.zoom, clamp(this.width / 1480, 0.64, 0.98), 1 - Math.exp(-dt * 4));
517:   }
518: 
519:   updateWeather(dt) {
520:     if (!this.state.settings.weather) return;
521:     const cfg = WEATHER[this.region.weather] || WEATHER.petals;
522:     for (const w of this.weather) {
523:       w.x += (w.vx + Math.sin(this.time * 0.7 + w.phase) * 8) * dt;
524:       w.y += w.vy * dt;
525:       if (w.y > this.height + 20) { w.y = -20; w.x = Math.random() * this.width; }
526:       if (w.x < -20) w.x = this.width + 15;
527:       if (w.x > this.width + 20) w.x = -15;
528:     }
529:   }
