531:   setMoveTargetFromScreen(sx, sy) {
532:     const zoom = this.camera.zoom;
533:     const ox = this.width / 2 + this.camera.shakeX;
534:     const oy = this.height * 0.57 + this.camera.shakeY;
535:     const gx = (sx - ox) / zoom + this.camera.x;
536:     const gy = (sy - oy) / zoom + this.camera.y;
537:     const u = (gx - this.world.origin.x) / (TILE / 2);
538:     const v = (gy - this.world.origin.y) / (TILE_H / 2);
539:     let tx = (u + v) / 2, ty = (v - u) / 2;
540:     tx = clamp(tx, 2, this.world.size - 2); ty = clamp(ty, 2, this.world.size - 2);
541:     this.input.target = { x: tx, y: ty };
542:   }
543: 
544:   _nearestEnemy(maxRange = 7, includeBoss = true) {
545:     let best = null;
546:     for (const e of this.enemies) {
547:       if (!e.alive || (e.isBoss && !includeBoss)) continue;
548:       const d = Math.hypot(e.x - this.player.x, e.y - this.player.y);
549:       if (d < maxRange && (!best || d < best.dist)) best = { enemy: e, dist: d };
550:     }
551:     return best;
552:   }
