554:   tryAttack() {
555:     if (this.modalOpen || this.player.dead || this.playerAttackCooldown > 0) return;
556:     const cls = CLASSES[this.state.profile.classId];
557:     this.playerAttackCooldown = cls.attackCooldown;
558:     this.player.attackTimer = 0.3;
559:     const stats = computeStats(this.state);
560:     const target = this._nearestEnemy(cls.attackRange + 3.1);
561:     if (target) this.player.facing = target.enemy.x >= this.player.x ? 1 : -1;
562:     const crit = Math.random() < stats.crit;
563:     let dmg = stats.attack * (0.92 + Math.random() * 0.18) * (crit ? 1.72 : 1);
564:     const iso = this.world.iso(this.player.x, this.player.y);
565:     const weaponEffect = this.state.equipped.effect ? WEAPON_EFFECTS[this.state.equipped.effect] : null;
566:     const color = weaponEffect?.color || cls.colors.accent;
567:     if (this.state.profile.classId === 'dawnblade') {
568:       const angle = target ? Math.atan2(target.enemy.y - this.player.y, target.enemy.x - this.player.x) : (this.player.facing > 0 ? 0.25 : Math.PI - 0.25);
569:       this.effects.push({ type: 'slash', x: iso.x, y: iso.y - 23, time: 0, dur: 0.3, radius: 42, angle, color });
570:       let hits = 0;
571:       for (const e of this.enemies) {
572:         if (!e.alive) continue;
573:         const d = Math.hypot(e.x - this.player.x, e.y - this.player.y);
574:         if (d < cls.attackRange + (e.def.radius || 0)) {
575:           const ad = Math.atan2(e.y - this.player.y, e.x - this.player.x);
576:           let diff = Math.abs(ad - angle);
577:           if (diff > Math.PI) diff = TAU - diff;
578:           if (diff < 1.6 || d < 1.0) { this.damageEnemy(e, dmg, crit, color); hits++; }
579:         }
580:       }
581:       if (hits) this.camera.shake = 2.2;
582:       this.effects.push({ type: 'swing', x: iso.x, y: iso.y, color, time: 0, dur: .28, facing: this.player.facing });
583:     } else if (this.state.profile.classId === 'voidcaller') {
584:       const targetE = target?.enemy || null;
585:       let tx, ty;
586:       if (targetE) { tx = targetE.x; ty = targetE.y; }
587:       else {
588:         const ang = this.player.facing > 0 ? -0.35 : Math.PI + 0.35;
589:         tx = this.player.x + Math.cos(ang) * 4.2; ty = this.player.y + Math.sin(ang) * 3.2;
590:       }
591:       const ang = Math.atan2(ty - this.player.y, tx - this.player.x);
592:       const speed = 11;
593:       this.projectiles.push({
594:         owner: 'player', x: this.player.x, y: this.player.y - 0.4, tx, ty, target: targetE,
595:         vx: Math.cos(ang) * speed, vy: Math.sin(ang) * speed, life: 1.4, damage: dmg, crit,
596:         color, radius: .2, arcane: true,
597:       });
598:       this.effects.push({ type: 'cast', x: iso.x, y: iso.y - 28, color, time: 0, dur: 0.25 });
599:     } else {
600:       const targetE = target?.enemy || null;
601:       let ang;
602:       if (targetE) ang = Math.atan2(targetE.y - this.player.y, targetE.x - this.player.x);
603:       else ang = this.player.facing > 0 ? -0.2 : Math.PI + 0.2;
604:       for (const s of [-1, 1]) {
605:         this.projectiles.push({
606:           owner: 'player', x: this.player.x, y: this.player.y, tx: this.player.x + Math.cos(ang) * 5,
607:           ty: this.player.y + Math.sin(ang) * 5, target: targetE,
608:           vx: Math.cos(ang + s * 0.045) * 12, vy: Math.sin(ang + s * 0.045) * 12,
609:           life: 1.1, damage: dmg * 0.58, crit, color, radius: .17, dagger: true,
610:         });
611:       }
612:       this.effects.push({ type: 'dashLine', x: iso.x, y: iso.y, color, time: 0, dur: .22 });
613:     }
614:   }
