616:   trySkill() {
617:     if (this.modalOpen || this.player.dead || this.skillCooldown > 0) return;
618:     const cls = CLASSES[this.state.profile.classId];
619:     const skill = cls.skill;
620:     if (!spendMana(this.state, skill.mana)) { this.ui?.toast('warn', 'Not enough mana.'); return; }
621:     this.skillCooldown = Math.max(2.4, skill.cooldown - (this.state.skillLevel - 1) * 0.11);
622:     const stats = computeStats(this.state);
623:     const target = this._nearestEnemy(11);
624:     let tx = target?.enemy.x ?? this.player.x + (this.player.facing > 0 ? 3 : -3);
625:     let ty = target?.enemy.y ?? this.player.y + 1.4;
626:     const levelMult = 1 + (this.state.skillLevel - 1) * 0.155;
627:     const radius = skill.radius + (this.state.skillLevel - 1) * 0.055;
628:     const dmg = stats.attack * skill.baseDamage * levelMult;
629:     const iso = this.world.iso(this.player.x, this.player.y);
630:     this.player.attackTimer = 0.55;
631:     if (skill.type === 'verdict') {
632:       this.camera.shake = 7;
633:       this.effects.push({ type: 'skillBurst', x: iso.x, y: iso.y - 25, color: skill.color, time: 0, dur: 0.9, radius: radius * TILE * 0.6 });
634:       const offsets = [[0, 0], [-1.4, 1.3], [1.5, 1.1]];
635:       offsets.forEach(([ox, oy], i) => {
636:         const bx = tx + ox, by = ty + oy;
637:         this.effects.push({ type: 'beam', x: this.world.iso(bx, by).x, y: this.world.iso(bx, by).y, color: skill.color, time: -i * 0.1, dur: 0.7, height: 280 });
638:         this.damageArea(bx, by, radius * 0.72, dmg * (i === 0 ? 1.3 : 0.9), skill.color);
639:       });
640:       this.damageArea(tx, ty, radius, dmg * 0.45, skill.color);
641:       this.ui?.toast('skill', `${skill.name}!`);
642:     } else if (skill.type === 'singularity') {
643:       this.camera.shake = 5;
644:       this.zones.push({
645:         owner: 'player', type: 'singularity', x: tx, y: ty, radius, ticks: 5, interval: 0.30, tickTimer: 0.1, tickIndex: 0,
646:         time: 0, color: skill.color, damage: dmg * 0.62,
647:       });
648:       this.ui?.toast('skill', `${skill.name}!`);
649:     } else {
650:       this.camera.shake = 4;
651:       this.zones.push({
652:         owner: 'player', type: 'barrage', x: tx, y: ty, radius, ticks: 5, interval: 0.25, tickTimer: 0.08, tickIndex: 0,
653:         time: 0, color: skill.color, damage: dmg * 0.5,
654:       });
655:       this.ui?.toast('skill', `${skill.name}!`);
656:     }
657:   }
