659:   damageArea(x, y, radius, damage, color) {
660:     const stats = computeStats(this.state);
661:     for (const e of this.enemies) {
662:       if (!e.alive) continue;
663:       if (Math.hypot(e.x - x, e.y - y) < radius) this.damageEnemy(e, damage, Math.random() < stats.crit, color);
664:     }
665:   }
