667:   damageEnemy(enemy, damage, crit = false, color = '#ffd36b') {
668:     if (!enemy.alive) return;
669:     enemy.hp -= damage;
670:     enemy.hitFlash = 0.15;
671:     enemy.aggro = true;
672:     const iso = this.world.iso(enemy.x, enemy.y);
673:     this.texts.push({ x: iso.x + (Math.random() - .5) * 20, y: iso.y - 45 - (enemy.def.size || 1) * 9, text: Math.round(damage).toString(), color: crit ? '#ffd36b' : '#fff4df', crit, time: 0, dur: 0.95, vy: -32 });
674:     this.effects.push({ type: 'impact', x: iso.x, y: iso.y - 20, color, time: 0, dur: 0.25, count: crit ? 9 : 5 });
675:     this.hitStop = crit ? 0.035 : 0.012;
676:     this.ui?.refreshHud();
677:     if (enemy.hp <= 0) this.killEnemy(enemy);
678:   }
679: 
680:   killEnemy(enemy) {
681:     if (!enemy.alive) return;
682:     enemy.alive = false;
683:     enemy.respawnTimer = enemy.isBoss ? 90 : 16 + Math.random() * 8;
684:     enemy.aggro = false;
685:     const iso = this.world.iso(enemy.x, enemy.y);
686:     this.effects.push({ type: 'death', x: iso.x, y: iso.y - 20, color: enemy.def.colors?.[2] || '#fff', time: 0, dur: 0.7, count: 16 });
687:     this.camera.shake = enemy.isBoss ? 14 : 3;
688:     this.state.stats.kills += 1;
689:     if (enemy.isBoss) this.state.stats.bosses += 1;
690:     const level = this.state.level;
691:     const xpGain = Math.round(enemy.def.xp * (1 + Math.max(0, enemy.def.level - level) * 0.015));
692:     const leveled = gainXp(this.state, xpGain);
693:     const gold = Math.round((enemy.def.gold[0] + Math.random() * (enemy.def.gold[1] - enemy.def.gold[0])) * (enemy.isBoss ? 1.1 : 1));
694:     addGold(this.state, gold);
695:     this.texts.push({ x: iso.x, y: iso.y - 60, text: `+${Math.round(xpGain)} XP`, color: '#9fe0ff', time: 0, dur: 1.2, vy: -24 });
696:     this.texts.push({ x: iso.x + 25, y: iso.y - 44, text: `+${gold} gold`, color: '#ffd877', time: 0, dur: 1.1, vy: -22 });
697:     // Equipment: direct drops are ALWAYS T3. Rarity follows config weights.
698:     const drop = rollEquipmentDrop(this.state, enemy.isBoss ? 'boss' : enemy.elite ? 'elite' : 'normal');
699:     if (drop) {
700:       this.pickups.push({ type: 'equipment', x: enemy.x, y: enemy.y, key: drop.key, info: drop.info, time: 0, bob: Math.random() * TAU });
701:       if (enemy.isBoss) {
702:         // boss guarantees a second direct T3 pickup, still within the same direct-drop rules
703:         const extra = rollEquipmentDrop(this.state, 'boss');
704:         if (extra) this.pickups.push({ type: 'equipment', x: enemy.x + 0.6, y: enemy.y - 0.5, key: extra.key, info: extra.info, time: 0, bob: Math.random() * TAU });
705:       }
706:     }
707:     if (enemy.isBoss) {
708:       const resource = this.region.resource;
709:       this.state.materials[resource.id] = (this.state.materials[resource.id] || 0) + (this.regionId === 'tower' ? 3 : 2);
710:       this.state.bossDefeated[this.regionId] = true;
711:       this.pickups.push({ type: 'material', x: enemy.x - 0.6, y: enemy.y + 0.4, material: resource, amount: 2, time: 0, bob: 1.2 });
712:       this.ui?.toast('boss', `${enemy.def.name} has fallen!`);
713:       this.ui?.bossDefeated(enemy);
714:       this.bossVisible = null; this.ui?.setBoss(null);
715:     }
716:     // quest progress for region trials and repeatable bounties
717:     const updates = notifyKill(this.state, this.regionId, enemy.def.id, enemy.isBoss);
718:     for (const u of updates) {
719:       if (u.type === 'complete') this.ui?.toast('quest', 'Trial complete! Open Quests to claim your reward.');
720:       else this.ui?.toast('quest', u.text);
721:     }
722:     if (!enemy.isBoss) {
723:       const bounty = progressBounty(this.state, this.regionId, enemy.def.id);
724:       if (bounty?.done) this.ui?.toast('quest', 'Bounty ready to claim.');
725:     }
726:     if (leveled.levels.length) {
727:       this.ui?.levelUp(leveled.levels[leveled.levels.length - 1]);
728:       this.effects.push({ type: 'levelup', x: this.world.iso(this.player.x, this.player.y).x, y: this.world.iso(this.player.x, this.player.y).y, color: '#ffe28a', time: 0, dur: 1.4, radius: 150 });
729:     }
730:     this.ui?.refreshHud(true);
731:     this.saveSoon();
732:   }
