734:   damagePlayer(amount, source) {
735:     if (this.player.dead || this.player.invuln > 0) return;
736:     const stats = computeStats(this.state);
737:     const mitigated = Math.max(1, amount * (100 / (100 + stats.armor * 2.2)));
738:     this.state.hp -= mitigated;
739:     this.player.hitFlash = 0.22;
740:     this.player.invuln = 0.38;
741:     this.camera.shake = Math.max(this.camera.shake, 5);
742:     this.ui?.flashDamage();
743:     const iso = this.world.iso(this.player.x, this.player.y);
744:     this.texts.push({ x: iso.x, y: iso.y - 54, text: `-${Math.round(mitigated)}`, color: '#ff7e72', time: 0, dur: 0.9, vy: -28 });
745:     this.spawnImpact(this.player.x, this.player.y, '#ff7e72', 7);
746:     this.ui?.refreshHud();
747:     if (this.state.hp <= 0) this.die();
748:   }
