799:   collectPickup(pickup) {
800:     if (pickup.collected) return;
801:     pickup.collected = true;
802:     if (pickup.type === 'equipment') {
803:       const added = addItem(this.state, pickup.key, 1);
804:       if (!added) {
805:         // No item destruction: overflow goes directly to the vault.
806:         this.state.storage[pickup.key] = (this.state.storage[pickup.key] || 0) + 1;
807:         this.ui?.toast('warn', `Satchel full — ${pickup.info.name} sent to your vault.`);
808:       } else {
809:         this.ui?.toast('loot', `Found ${pickup.info.rarityName} ${pickup.info.name} (T3).`);
810:       }
811:       this.effects.push({ type: 'lootBurst', x: this.world.iso(pickup.x, pickup.y).x, y: this.world.iso(pickup.x, pickup.y).y - 20, color: pickup.info.rarityColor, time: 0, dur: 0.6 });
812:     } else if (pickup.type === 'material') {
813:       this.state.materials[pickup.material.id] = (this.state.materials[pickup.material.id] || 0) + (pickup.amount || 1);
