1223:   drawWorldEffects(ctx) {
1224:     for (const fx of this.effects) {
1225:       if (fx.time < 0) continue;
1226:       const prog = clamp(fx.time / fx.dur, 0, 1);
1227:       ctx.save();
1228:       if (fx.type === 'slash') {
1229:         ctx.translate(fx.x, fx.y);
1230:         ctx.rotate(fx.angle);
1231:         ctx.globalCompositeOperation = 'lighter';
1232:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .9); ctx.lineWidth = 5 * (1 - prog) + 1;
1233:         ctx.beginPath(); ctx.arc(0, 0, fx.radius * (0.7 + prog * .35), -1.05, 1.05); ctx.stroke();
1234:         ctx.strokeStyle = rgba('#fff7d6', (1 - prog) * .6); ctx.lineWidth = 1.4;
1235:         ctx.beginPath(); ctx.arc(0, 0, fx.radius * (0.68 + prog * .35), -1.05, 1.05); ctx.stroke();
1236:       } else if (fx.type === 'swing') {
1237:         ctx.translate(fx.x, fx.y - 16);
1238:         ctx.fillStyle = rgba(fx.color, (1 - prog) * .2);
1239:         ctx.beginPath(); ctx.ellipse(0, 0, 30 * prog + 5, 6, 0, 0, TAU); ctx.fill();
1240:       } else if (fx.type === 'impact') {
1241:         ctx.translate(fx.x, fx.y);
1242:         ctx.globalCompositeOperation = 'lighter';
1243:         for (let i = 0; i < fx.count; i++) {
1244:           const a = i / fx.count * TAU + prog * 1.5;
1245:           const r = 8 + prog * 30;
1246:           ctx.fillStyle = rgba(fx.color, 1 - prog);
1247:           ctx.fillRect(Math.cos(a) * r, Math.sin(a) * r * .6, 2.5, 2.5);
1248:         }
1249:         const g = ctx.createRadialGradient(0, 0, 1, 0, 0, 22);
1250:         g.addColorStop(0, rgba('#fff4d4', (1 - prog) * .8)); g.addColorStop(1, rgba(fx.color, 0));
1251:         ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, 22, 0, TAU); ctx.fill();
1252:       } else if (fx.type === 'death') {
1253:         ctx.translate(fx.x, fx.y);
1254:         ctx.globalCompositeOperation = 'lighter';
1255:         for (let i = 0; i < fx.count; i++) {
1256:           const a = i / fx.count * TAU;
1257:           const r = 8 + prog * 46;
1258:           ctx.fillStyle = rgba(fx.color, (1 - prog) * .75);
1259:           ctx.fillRect(Math.cos(a) * r, Math.sin(a) * r * .65 - prog * 20, 2, 2 + (1 - prog) * 3);
1260:         }
1261:         ctx.globalCompositeOperation = 'source-over';
1262:         ctx.fillStyle = rgba('#141018', (1 - prog) * .25);
1263:         ctx.beginPath(); ctx.ellipse(0, 4, 20 + prog * 12, 7, 0, 0, TAU); ctx.fill();
1264:       } else if (fx.type === 'beam') {
1265:         ctx.translate(fx.x, fx.y);
1266:         ctx.globalCompositeOperation = 'lighter';
1267:         const g = ctx.createLinearGradient(0, -fx.height, 0, 0);
1268:         g.addColorStop(0, rgba(fx.color, 0)); g.addColorStop(.25, rgba(fx.color, .15 * (1 - prog))); g.addColorStop(1, rgba(fx.color, .8 * (1 - prog)));
1269:         ctx.fillStyle = g;
1270:         const width = 18 + Math.sin(prog * Math.PI) * 22;
1271:         ctx.fillRect(-width / 2, -fx.height, width, fx.height);
1272:         ctx.fillStyle = rgba('#fff8d9', (1 - prog) * .5);
1273:         ctx.fillRect(-4, -fx.height, 8, fx.height);
1274:         ctx.restore();
1275:         ctx.save(); ctx.translate(fx.x, fx.y); ctx.scale(1, .5);
1276:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .8); ctx.lineWidth = 3;
1277:         ctx.beginPath(); ctx.arc(0, 0, 35 + prog * 20, 0, TAU); ctx.stroke();
1278:         ctx.fillStyle = rgba(fx.color, (1 - prog) * .16); ctx.beginPath(); ctx.arc(0, 0, 35 + prog * 20, 0, TAU); ctx.fill();
1279:       } else if (fx.type === 'shock' || fx.type === 'zonePulse') {
1280:         ctx.translate(fx.x, fx.y); ctx.scale(1, .5);
1281:         ctx.globalCompositeOperation = 'lighter';
1282:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .85); ctx.lineWidth = 4 * (1 - prog) + 1;
1283:         ctx.beginPath(); ctx.arc(0, 0, fx.radius * (0.3 + prog * .8), 0, TAU); ctx.stroke();
1284:         ctx.fillStyle = rgba(fx.color, (1 - prog) * .08); ctx.beginPath(); ctx.arc(0, 0, fx.radius * (0.3 + prog * .8), 0, TAU); ctx.fill();
1285:       } else if (fx.type === 'heal') {
1286:         ctx.translate(fx.x, fx.y);
1287:         ctx.globalCompositeOperation = 'lighter';
1288:         for (let i = 0; i < 9; i++) {
1289:           const a = i / 9 * TAU;
1290:           const y = 30 - prog * 70 - (i % 3) * 12;
1291:           ctx.fillStyle = rgba(fx.color, (1 - prog) * .7);
1292:           ctx.fillRect(Math.cos(a) * 13, y, 2, 5);
1293:         }
1294:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .6); ctx.lineWidth = 1.5;
1295:         ctx.beginPath(); ctx.ellipse(0, 2, 22, 8, 0, 0, TAU); ctx.stroke();
1296:       } else if (fx.type === 'levelup') {
1297:         ctx.translate(fx.x, fx.y);
1298:         ctx.globalCompositeOperation = 'lighter';
1299:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .9); ctx.lineWidth = 4;
1300:         ctx.beginPath(); ctx.ellipse(0, 0, 30 + prog * fx.radius, 10 + prog * fx.radius * .3, 0, 0, TAU); ctx.stroke();
1301:         for (let i = 0; i < 18; i++) {
1302:           const a = i / 18 * TAU;
1303:           ctx.fillStyle = rgba(fx.color, (1 - prog) * .8);
1304:           ctx.fillRect(Math.cos(a) * (20 + prog * 55), -prog * 120 + Math.sin(a) * 10, 2, 2);
1305:         }
1306:       } else if (fx.type === 'skillBurst') {
1307:         ctx.translate(fx.x, fx.y);
1308:         ctx.globalCompositeOperation = 'lighter';
1309:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .8); ctx.lineWidth = 3;
1310:         for (let i = 0; i < 5; i++) {
1311:           ctx.beginPath(); ctx.arc(0, 0, (fx.radius + i * 18) * (0.2 + prog), 0, TAU); ctx.stroke();
1312:         }
1313:         const g = ctx.createRadialGradient(0, 0, 2, 0, 0, 100 * prog);
1314:         g.addColorStop(0, rgba('#fff8d6', (1 - prog) * .45)); g.addColorStop(1, rgba(fx.color, 0));
1315:         ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, 100 * prog, 0, TAU); ctx.fill();
1316:       } else if (fx.type === 'lootBurst') {
1317:         ctx.translate(fx.x, fx.y);
1318:         ctx.globalCompositeOperation = 'lighter';
1319:         for (let i = 0; i < 10; i++) { const a = i / 10 * TAU + prog; const r = 9 + prog * 28; ctx.fillStyle = rgba(fx.color, (1 - prog) * .8); ctx.fillRect(Math.cos(a) * r, Math.sin(a) * r, 2, 2); }
1320:       } else if (fx.type === 'cast') {
1321:         ctx.translate(fx.x, fx.y);
1322:         ctx.globalCompositeOperation = 'lighter';
1323:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .7); ctx.lineWidth = 1.5;
1324:         ctx.beginPath(); ctx.arc(0, 0, 12 + prog * 25, 0, TAU); ctx.stroke();
1325:         ctx.beginPath(); ctx.arc(0, 0, 6 + prog * 18, -1, 2); ctx.stroke();
1326:       } else if (fx.type === 'dashLine') {
1327:         ctx.translate(fx.x, fx.y - 15);
1328:         ctx.globalCompositeOperation = 'lighter';
1329:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .45); ctx.lineWidth = 2;
1330:         ctx.beginPath(); ctx.moveTo(-35 * (1 - prog), 0); ctx.lineTo(35 * (1 - prog), 0); ctx.stroke();
1331:       } else if (fx.type === 'step') {
1332:         ctx.translate(fx.x, fx.y); ctx.scale(1, .45);
1333:         ctx.strokeStyle = rgba(fx.color, (1 - prog) * .22); ctx.lineWidth = 1;
1334:         ctx.beginPath(); ctx.arc(0, 0, 8 + prog * 12, 0, TAU); ctx.stroke();
1335:       }
1336:       ctx.restore();
1337:     }
1338:     // particles from hits
1339:     for (const p of this.particles) {
1340:       const a = clamp(1 - (1 - p.life / p.max), 0, 1);
1341:       ctx.globalAlpha = Math.max(0, p.life / p.max);
1342:       ctx.fillStyle = p.color;
1343:       ctx.fillRect(p.x, p.y, p.size, p.size);
1344:     }
1345:     ctx.globalAlpha = 1;
1346:   }
