1366:   drawLabels(ctx, originX, originY, zoom) {
1367:     const camX = this.camera.x, camY = this.camera.y;
1368:     const toScreen = (p) => ({ x: (p.x - camX) * zoom + originX, y: (p.y - camY) * zoom + originY });
1369:     // NPC names and quest markers
1370:     for (const npc of this.world.npcs) {
1371:       if (npc.service === 'waystone') continue;
1372:       const p = toScreen(this.world.iso(npc.x, npc.y));
1373:       if (p.x < -80 || p.x > this.width + 80 || p.y < -80 || p.y > this.height + 80) continue;
1374:       const quest = this.state.quests[this.state.trackedQuest || ''];
1375:       const regionQuest = this.region.quest;
1376:       let marker = '';
1377:       let markerColor = '#ffd36b';
1378:       if (npc.service === 'questgiver') {
1379:         const q = this.state.quests[`trial_${this.regionId}`];
1380:         if (!q || q.status === 'active') { marker = q?.status === 'complete' ? '?' : '!'; }
1381:         else if (q.status === 'complete') { marker = '?'; markerColor = '#8fe9a6'; }
1382:       }
1383:       ctx.save();
1384:       ctx.textAlign = 'center';
1385:       if (npc.kind === 'pilgrim' || this.distanceToPlayer(npc.x, npc.y) < 6) {
1386:         ctx.font = `600 ${Math.max(9, 11 * zoom)}px "Trebuchet MS", sans-serif`;
1387:         ctx.fillStyle = 'rgba(241,232,210,.88)';
1388:         ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(9,13,20,.68)';
1389:         ctx.strokeText(npc.name, p.x, p.y - 50 * zoom);
1390:         ctx.fillText(npc.name, p.x, p.y - 50 * zoom);
1391:         ctx.font = `${Math.max(7, 8 * zoom)}px "Trebuchet MS", sans-serif`;
1392:         ctx.fillStyle = npc.kind === 'pilgrim' ? (npc.faction === 'angel' ? 'rgba(255,231,160,.75)' : 'rgba(255,145,112,.8)') : 'rgba(191,190,178,.68)';
1393:         ctx.fillText(npc.title, p.x, p.y - 39 * zoom);
1394:       }
1395:       if (marker) {
1396:         const yy = p.y - 66 * zoom + Math.sin(this.time * 3) * 2;
1397:         ctx.fillStyle = 'rgba(10,14,22,.82)'; ctx.beginPath(); ctx.arc(p.x, yy, 9, 0, TAU); ctx.fill();
1398:         ctx.strokeStyle = markerColor; ctx.lineWidth = 1.5; ctx.stroke();
1399:         ctx.fillStyle = markerColor; ctx.font = `700 14px Georgia, serif`; ctx.fillText(marker, p.x, yy + 5);
1400:       }
1401:       ctx.restore();
1402:     }
1403:     // enemy names/health
1404:     for (const e of this.enemies) {
1405:       if (!e.alive) continue;
1406:       const p = toScreen(this.world.iso(e.x, e.y));
1407:       if (p.x < -100 || p.x > this.width + 100 || p.y < -100 || p.y > this.height + 100) continue;
1408:       const d = this.distanceToPlayer(e.x, e.y);
1409:       if (!e.aggro && d > 6 && !e.isBoss) continue;
1410:       const size = e.def.size || 1;
1411:       const barW = Math.max(24, (e.isBoss ? 82 : 38) * zoom);
1412:       const barY = p.y - (e.isBoss ? 80 : 46 + size * 12) * zoom;
1413:       if (e.isBoss) {
1414:         ctx.save(); ctx.textAlign = 'center'; ctx.font = `700 ${Math.max(10, 12 * zoom)}px Georgia, serif`;
1415:         ctx.fillStyle = 'rgba(255,224,173,.9)'; ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(11,12,18,.8)';
1416:         ctx.strokeText(e.def.name, p.x, barY - 8); ctx.fillText(e.def.name, p.x, barY - 8);
1417:         ctx.restore();
1418:       } else if (e.elite || e.aggro) {
1419:         ctx.save(); ctx.textAlign = 'center'; ctx.font = `600 ${Math.max(8, 9 * zoom)}px "Trebuchet MS", sans-serif`;
1420:         ctx.fillStyle = e.elite ? 'rgba(255,191,107,.92)' : 'rgba(238,232,214,.85)'; ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(9,12,18,.7)';
1421:         ctx.strokeText(e.def.name, p.x, barY - 5); ctx.fillText(e.def.name, p.x, barY - 5); ctx.restore();
1422:       }
1423:       const hpPct = clamp(e.hp / e.maxHp, 0, 1);
1424:       ctx.fillStyle = 'rgba(7,10,14,.72)'; ctx.fillRect(p.x - barW / 2, barY, barW, Math.max(3, 4 * zoom));
1425:       ctx.fillStyle = e.isBoss ? '#e35959' : e.elite ? '#ffab52' : '#cf665b';
1426:       ctx.fillRect(p.x - barW / 2 + 1, barY + 1, (barW - 2) * hpPct, Math.max(1.5, 2.5 * zoom));
1427:       if (e.def.ranged) { ctx.fillStyle = 'rgba(167,216,255,.7)'; ctx.fillRect(p.x + barW / 2 + 3, barY, 2, 2); }
