1429:     // player target marker
1430:     if (this.ui?.selectedEnemy && this.ui.selectedEnemy.alive) {
1431:       const p = toScreen(this.world.iso(this.ui.selectedEnemy.x, this.ui.selectedEnemy.y));
1432:       ctx.save(); ctx.strokeStyle = 'rgba(255,220,141,.65)'; ctx.lineWidth = 1.5;
1433:       ctx.beginPath(); ctx.ellipse(p.x, p.y, 23, 8, 0, 0, TAU); ctx.stroke(); ctx.restore();
