1438:       ctx.save(); ctx.textAlign = 'center'; ctx.font = `700 ${Math.max(10, 12 * zoom)}px Georgia, serif`;
1439:       ctx.fillStyle = 'rgba(255,230,166,.8)'; ctx.fillText('E', p.x, p.y - 66 * zoom);
1440:       ctx.restore();
1441:     }
1442:   }
