1446:   drawLighting(ctx, W, H, originX, originY, zoom) {
1447:     const camX = this.camera.x, camY = this.camera.y;
1448:     ctx.save();
1449:     ctx.globalCompositeOperation = 'screen';
1450:     for (const light of this.world.lights) {
1451:       const p = this.world.iso(light.x, light.y);
1452:       const sx = (p.x - camX) * zoom + originX;
1453:       const sy = (p.y - camY) * zoom + originY - 16;
1454:       if (sx < -300 || sx > W + 300 || sy < -300 || sy > H + 300) continue;
1455:       const flicker = 1 + Math.sin(this.time * 6 + light.phase) * (light.flicker || 0);
1456:       const r = (light.radius || 4) * TILE * .48 * zoom * flicker;
1457:       const g = ctx.createRadialGradient(sx, sy, 1, sx, sy, r);
1458:       g.addColorStop(0, rgba(light.color, (light.intensity || .3) * .48));
1459:       g.addColorStop(.45, rgba(light.color, (light.intensity || .3) * .13));
1460:       g.addColorStop(1, rgba(light.color, 0));
1461:       ctx.fillStyle = g; ctx.beginPath(); ctx.arc(sx, sy, r, 0, TAU); ctx.fill();
1462:     }
1463:     // broad sun / ambient bloom
1464:     const sun = ctx.createRadialGradient(W * .16, H * .14, 10, W * .16, H * .14, W * .65);
1465:     const tint = this.region.biome === 'astral' ? '#b8a8ff' : this.region.biome === 'volcanic' ? '#ff8c57' : '#ffe1a0';
1466:     sun.addColorStop(0, rgba(tint, .07)); sun.addColorStop(1, rgba(tint, 0));
1467:     ctx.fillStyle = sun; ctx.fillRect(0, 0, W, H);
1468:     ctx.restore();
1469:     // Color grade
1470:     ctx.save();
1471:     ctx.globalCompositeOperation = 'soft-light';
1472:     ctx.fillStyle = this.region.palette.ambient;
1473:     ctx.fillRect(0, 0, W, H);
1474:     ctx.restore();
1475:     // Fog bands
1476:     const fog = this.region.palette.fog;
1477:     if (fog) {
1478:       ctx.save();
1479:       const drift = (this.time * 4) % (W + 400) - 200;
1480:       for (let i = 0; i < 3; i++) {
1481:         const g = ctx.createLinearGradient(0, H * .35 + i * 90, 0, H * .7 + i * 40);
1482:         g.addColorStop(0, rgba(fog.match(/[\d.]+/)?.[0] ? '#cbd8e6' : '#cbd8e6', 0));
1483:         g.addColorStop(.5, fog);
1484:         g.addColorStop(1, rgba('#cbd8e6', 0));
1485:         ctx.fillStyle = g;
1486:         ctx.beginPath(); ctx.ellipse(drift + i * 380, H * .52 + i * 55, 320, 50, 0, 0, TAU); ctx.fill();
1487:       }
1488:       ctx.restore();
1489:     }
1490:   }
