1492:   drawWeather(ctx, W, H) {
1493:     const cfg = WEATHER[this.region.weather] || WEATHER.petals;
1494:     ctx.save();
1495:     for (const w of this.weather) {
1496:       ctx.globalAlpha = w.alpha;
1497:       if (cfg.kind === 'mist') {
1498:         const g = ctx.createRadialGradient(w.x, w.y, 1, w.x, w.y, w.size);
1499:         g.addColorStop(0, rgba(w.color, .08)); g.addColorStop(1, rgba(w.color, 0));
1500:         ctx.fillStyle = g; ctx.beginPath(); ctx.ellipse(w.x, w.y, w.size, w.size * .25, 0, 0, TAU); ctx.fill();
1501:       } else if (cfg.kind === 'petal') {
1502:         ctx.save(); ctx.translate(w.x, w.y); ctx.rotate(this.time + w.phase); ctx.fillStyle = w.color;
1503:         ctx.beginPath(); ctx.ellipse(0, 0, w.size, w.size * .45, 0, 0, TAU); ctx.fill(); ctx.restore();
1504:       } else if (cfg.kind === 'ember' || cfg.kind === 'glow') {
1505:         const g = ctx.createRadialGradient(w.x, w.y, 0, w.x, w.y, w.size * 3);
1506:         g.addColorStop(0, rgba(w.color, .5)); g.addColorStop(1, rgba(w.color, 0));
1507:         ctx.fillStyle = g; ctx.beginPath(); ctx.arc(w.x, w.y, w.size * 3, 0, TAU); ctx.fill();
1508:         ctx.fillStyle = w.color; ctx.fillRect(w.x, w.y, w.size, w.size);
1509:       } else if (cfg.kind === 'star') {
1510:         ctx.fillStyle = w.color; ctx.fillRect(w.x, w.y, w.size, w.size);
1511:         if (Math.sin(this.time * 2 + w.phase) > .75) { ctx.globalAlpha = w.alpha * .4; ctx.fillRect(w.x - 3, w.y + .5, 8, .7); ctx.fillRect(w.x + .5, w.y - 3, .7, 8); }
1512:       } else {
1513:         ctx.fillStyle = w.color; ctx.fillRect(w.x, w.y, w.size, w.size);
1514:       }
1515:     }
1516:     ctx.restore();
1517:   }
