1519:   drawVignette(ctx, W, H) {
1520:     const g = ctx.createRadialGradient(W / 2, H * .55, Math.min(W, H) * .28, W / 2, H * .55, Math.max(W, H) * .78);
1521:     g.addColorStop(0, 'rgba(4,7,12,0)'); g.addColorStop(.72, 'rgba(4,7,12,.12)'); g.addColorStop(1, 'rgba(3,5,9,.52)');
1522:     ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
